/**
 * Standard API Response Envelopes
 * Strictly matches the backend DRF custom exception handler and response format.
 */

/**
 * Successful API response envelope.
 * Defaults to `data: null` for endpoints that return null data (such as logout, password reset),
 * or where `data` is omitted by the backend (such as resend email verification).
 */
export interface ApiResponse<T = null> {
  success: true
  message: string
  data?: T
}

/**
 * Standard API error response envelope.
 * Generated by apps.core.exceptions.custom_exception_handler.
 */
export interface ApiErrorResponse {
  success: false
  message: string
  errors?: Record<string, string[]> | Record<string, unknown> | string[] | null
}

